<template>

  <CoreTable :emptyMessage="noResourcesInLessonLabel$()">
    <template #headers>
      <th>{{ titleLabel$() }}</th>
      <th>{{ progressLabel$() }}</th>
      <th>{{ avgTimeSpentLabel$() }}</th>
      <td v-if="editable"><!-- Actions --></td>
    </template>
    <template #tbody>
      <DraggableRegion
        :items="entries"
        @update:items="handleResourcesOrderChange"
      >
        <tbody>
          <DraggableItem
            v-for="(tableRow, index) in entries"
            :key="tableRow.node_id"
          >
            <tr :style="{ backgroundColor: 'var(--tokens-surface)' }">
              <td>
                <div class="resource-title">
                  <DraggableHandle v-if="editable">
                    <!-- Mousedown.prevent is needed to avoid user selection -->
                    <DragSortWidget
                      class="sort-widget"
                      :isFirst="index === 0"
                      :isLast="index === entries.length - 1"
                      :itemLabel="tableRow.title"
                      :position="index + 1"
                      :total="entries.length"
                      @moveUp="moveUpOne(index)"
                      @moveDown="moveDownOne(index)"
                      @mousedown.prevent
                    />
                  </DraggableHandle>
                  <KIcon
                    :icon="tableRow.kind"
                    :color="tableRow.link ? $themeTokens.link : null"
                    class="resource-icon"
                  />
                  <KRouterLink
                    v-if="tableRow.link"
                    :text="tableRow.title"
                    :to="tableRow.link"
                  />
                  <span v-else>
                    {{ tableRow.title }}
                  </span>
                </div>
              </td>
              <td>
                <StatusSummary
                  v-if="tableRow.tally"
                  :tally="tableRow.tally"
                  :verbose="true"
                />
                <KEmptyPlaceholder v-else />
              </td>
              <td>
                <TimeDuration
                  v-if="tableRow.tally"
                  :seconds="tableRow.avgTimeSpent"
                />
                <KEmptyPlaceholder v-else />
              </td>
              <td v-if="editable">
                <div class="actions">
                  <KButton
                    v-if="tableRow.kind !== ContentNodeKinds.EXERCISE"
                    appearance="flat-button"
                    :text="questionsCountLabel$({ count: tableRow.promptCount || 0 })"
                    @click="$emit('editPrompts', tableRow)"
                  />
                  <KIconButton
                    icon="clear"
                    :ariaLabel="removeAction$()"
                    @click="() => handleRemoveEntry(tableRow)"
                  />
                </div>
              </td>
            </tr>
          </DraggableItem>
        </tbody>
      </DraggableRegion>
    </template>
  </CoreTable>

</template>


<script>

  import { mapState } from 'vuex';
  import CoreTable from 'kolibri/components/CoreTable';
  import TimeDuration from 'kolibri-common/components/TimeDuration';
  import { coreStrings } from 'kolibri/uiText/commonCoreStrings';
  import { ContentNodeKinds } from 'kolibri/constants';
  import { lessonResponsesStrings } from 'kolibri-common/strings/lessonResponsesStrings';
  import DraggableRegion from 'kolibri-common/components/draggable/DraggableRegion';
  import DraggableHandle from 'kolibri-common/components/draggable/DraggableHandle';
  import DragSortWidget from 'kolibri-common/components/draggable/DragSortWidget';
  import DraggableItem from 'kolibri-common/components/draggable/DraggableItem';
  import { coachStrings } from '../../../common/commonCoachStrings';
  import CSVExporter from '../../../../csv/exporter';
  import * as csvFields from '../../../../csv/fields';
  import StatusSummary from '../../../common/status/StatusSummary';

  export default {
    name: 'LessonResourcesTable',
    components: {
      CoreTable,
      StatusSummary,
      TimeDuration,
      DraggableRegion,
      DraggableHandle,
      DragSortWidget,
      DraggableItem,
    },
    setup() {
      const { resourcesLabel$, removeAction$, progressLabel$ } = coreStrings;
      const { noResourcesInLessonLabel$, titleLabel$, avgTimeSpentLabel$ } = coachStrings;
      const { questionsCountLabel$ } = lessonResponsesStrings;

      return {
        ContentNodeKinds,
        questionsCountLabel$,
        resourcesLabel$,
        removeAction$,
        noResourcesInLessonLabel$,
        titleLabel$,
        progressLabel$,
        avgTimeSpentLabel$,
      };
    },
    props: {
      title: {
        type: String,
        default: '',
      },
      entries: {
        type: Array,
        default: () => [],
      },
      editable: {
        type: Boolean,
        default: false,
      },
    },
    computed: {
      ...mapState('classSummary', { className: 'name' }),
      group() {
        return this.$route.params.groupId && this.groupMap[this.$route.params.groupId];
      },
    },
    methods: {
      handleResourcesOrderChange(newArray) {
        this.$emit('change', { newArray });
      },
      handleRemoveEntry(entry) {
        const newArray = this.entries.filter(({ node_id }) => node_id !== entry.node_id);
        this.handleResourcesOrderChange(newArray);
      },
      moveUpOne(oldIndex) {
        this.swap(oldIndex, oldIndex - 1);
      },
      moveDownOne(oldIndex) {
        this.swap(oldIndex, oldIndex + 1);
      },
      swap(oldIndex, newIndex) {
        const newArray = [...this.entries];
        const oldResource = newArray[newIndex];
        newArray[newIndex] = newArray[oldIndex];
        newArray[oldIndex] = oldResource;

        this.handleResourcesOrderChange(newArray);
      },
      /**
       * Triggers a CSV download of the resource progress data currently displayed in the table.
       * @public
       */
      exportCSV() {
        const columns = [
          ...csvFields.title(),
          ...csvFields.tally(),
          ...csvFields.timeSpent('avgTimeSpent', this.avgTimeSpentLabel$()),
        ];

        const exporter = new CSVExporter(columns, this.className);
        exporter.addNames({
          lesson: this.title,
          resources: this.resourcesLabel$(),
        });

        if (this.group) {
          exporter.addNames({
            group: this.group.name,
          });
        }

        exporter.export(this.entries);
      },
    },
  };

</script>


