<template>

  <div class="metadata-chips">
    <div
      v-for="{ label, key, icon } in tags"
      :key="key"
      :style="{ backgroundColor: 'var(--palette-grey-v100)' }"
      class="chip"
    >
      <KIcon
        v-if="icon"
        class="icon"
        :icon="icon"
      />
      <span
        class="chip-text"
        :style="{ color: 'var(--palette-grey-v700)' }"
      >
        {{ label }}
      </span>
    </div>
  </div>

</template>


<script>

  /**
   * @typedef  {object} Tag
   * @property {string} label - Visible chip label.
   * @property {string} key - Stable identifier for the tag.
   * @property {string} icon - Icon shown alongside the label.
   */

  export default {
    name: 'MetadataChips',
    props: {
      /**
       * A list of tags to display.
       * @type {Tag[]}
       */
      tags: {
        type: Array,
        required: true,
        validator: tags => tags.every(tag => tag.label && tag.key),
      },
    },
  };

</script>


